import Foundation

extension Deck {
    /// The Suit of Cups — water, emotion, love, intuition, and relationships. Ids 36...49.
    static let cups: [TarotCard] = [
        TarotCard(id: 36, name: "Ace of Cups", arcana: .minor, suit: .cups, number: 1, element: .water,
                  keywords: ["new love", "emotion", "compassion", "overflow"],
                  upright: "An overflowing cup of new love, compassion, and emotional renewal. Open your heart and let feeling flow.",
                  reversed: "Blocked or guarded emotions, a heart held back. Tend to what you've been holding in before it spills over."),
        TarotCard(id: 37, name: "Two of Cups", arcana: .minor, suit: .cups, number: 2, element: .water,
                  keywords: ["partnership", "connection", "mutual love", "harmony"],
                  upright: "A beautiful meeting of hearts — mutual respect, attraction, and balance. A partnership of equals is blossoming.",
                  reversed: "Imbalance or tension between two people. Restore the give-and-take, or acknowledge a connection that's fraying."),
        TarotCard(id: 38, name: "Three of Cups", arcana: .minor, suit: .cups, number: 3, element: .water,
                  keywords: ["friendship", "celebration", "community", "joy"],
                  upright: "Joyful celebration with friends and a sense of belonging. Gather your people and toast the good in your life.",
                  reversed: "Overindulgence, gossip, or feeling left out. Tend your true friendships and step back from the noise."),
        TarotCard(id: 39, name: "Four of Cups", arcana: .minor, suit: .cups, number: 4, element: .water,
                  keywords: ["apathy", "contemplation", "reevaluation", "discontent"],
                  upright: "Withdrawn contemplation and a quiet discontent with what's offered. Look up — an overlooked gift may be right beside you.",
                  reversed: "Re-engaging with life or accepting a new opportunity. The fog of apathy lifts and your interest returns."),
        TarotCard(id: 40, name: "Five of Cups", arcana: .minor, suit: .cups, number: 5, element: .water,
                  keywords: ["loss", "grief", "regret", "disappointment"],
                  upright: "Grief over what's been lost, eyes fixed on spilled cups. Honor the sorrow, then notice the two cups still standing.",
                  reversed: "Acceptance, forgiveness, and moving forward. You turn toward what remains and begin to heal."),
        TarotCard(id: 41, name: "Six of Cups", arcana: .minor, suit: .cups, number: 6, element: .water,
                  keywords: ["nostalgia", "memories", "innocence", "reunion"],
                  upright: "Warm nostalgia, innocent joy, and the comfort of familiar bonds. Revisit a happy memory or reconnect with your past.",
                  reversed: "Stuck in the past or idealizing what was. Cherish the memories, but live in the present you have now."),
        TarotCard(id: 42, name: "Seven of Cups", arcana: .minor, suit: .cups, number: 7, element: .water,
                  keywords: ["choices", "illusion", "fantasy", "wishful thinking"],
                  upright: "Many tempting options shimmer like dreams, not all of them real. Choose with clear eyes rather than fantasy.",
                  reversed: "Clarity returns and a decision becomes possible. Cut through the illusions and commit to one path."),
        TarotCard(id: 43, name: "Eight of Cups", arcana: .minor, suit: .cups, number: 8, element: .water,
                  keywords: ["walking away", "search", "transition", "letting go"],
                  upright: "Walking away from what no longer fulfills you in search of deeper meaning. Honor the courage it takes to leave.",
                  reversed: "Fear of leaving, or drifting back to what you outgrew. Decide whether to truly stay or finally go."),
        TarotCard(id: 44, name: "Nine of Cups", arcana: .minor, suit: .cups, number: 9, element: .water,
                  keywords: ["contentment", "satisfaction", "wishes", "gratitude"],
                  upright: "Emotional satisfaction and a wish fulfilled — the 'wish card.' Savor your contentment with genuine gratitude.",
                  reversed: "Smugness or a wish that rang hollow. Look past surface pleasures to what truly satisfies you."),
        TarotCard(id: 45, name: "Ten of Cups", arcana: .minor, suit: .cups, number: 10, element: .water,
                  keywords: ["harmony", "family", "fulfillment", "joy"],
                  upright: "Lasting emotional harmony, loving family, and a fulfilled heart. This is the deep joy of belonging.",
                  reversed: "A gap between the picture and the reality of home. Address the disconnection so the harmony can be real."),
        TarotCard(id: 46, name: "Page of Cups", arcana: .minor, suit: .cups, number: 11, element: .water,
                  keywords: ["creativity", "intuition", "wonder", "messages"],
                  upright: "A gentle messenger of intuition, creativity, and emotional wonder. Stay open to surprising feelings and tender ideas.",
                  reversed: "Emotional immaturity or ignored intuition. Let yourself feel without dismissing what your heart is telling you."),
        TarotCard(id: 47, name: "Knight of Cups", arcana: .minor, suit: .cups, number: 12, element: .water,
                  keywords: ["romance", "charm", "idealism", "following the heart"],
                  upright: "A romantic dreamer who follows the heart and offers it freely. Lead with feeling and pursue what moves you.",
                  reversed: "Moodiness, unrealistic ideals, or all charm and no substance. Ground your romantic vision in reality."),
        TarotCard(id: 48, name: "Queen of Cups", arcana: .minor, suit: .cups, number: 13, element: .water,
                  keywords: ["compassion", "intuition", "empathy", "emotional security"],
                  upright: "Deep compassion, intuition, and emotional steadiness. Hold space for yourself and others with a calm, caring heart.",
                  reversed: "Emotional overwhelm or martyrdom. Protect your own well before pouring into everyone else's."),
        TarotCard(id: 49, name: "King of Cups", arcana: .minor, suit: .cups, number: 14, element: .water,
                  keywords: ["emotional balance", "diplomacy", "wisdom", "calm"],
                  upright: "Mastery of emotion — calm, wise, and diplomatic under pressure. Lead with a steady heart and balanced mind.",
                  reversed: "Suppressed feelings or moody volatility. Reconnect to your emotions honestly instead of bottling or venting them.")
    ]
}
